mapper.select:
SELECT a.public_id, a.account_name, a.created_at, COALESCE(p.preferred_language, 'zh-CN') AS preferred_language
FROM account_auth_session s
JOIN account a ON a.id = s.account_id
LEFT JOIN account_preferences p ON p.account_id = a.id
WHERE s.access_token_hash = #{accessHash}
  AND s.status = 'ACTIVE'
  AND s.access_expires_at > #{now}
  AND s.absolute_expires_at > #{now}

mapper.update:
UPDATE account_auth_session
SET access_token_hash = #{accessHash}, access_expires_at = #{accessExpiresAt}, updated_at = #{updatedAt}
WHERE id = #{sessionId} AND status = 'ACTIVE'

UPDATE account_auth_session
SET status = 'REVOKED', revoked_at = #{revokedAt}, updated_at = #{revokedAt}
WHERE id = #{sessionId} AND status = 'ACTIVE'

mapper.select:
SELECT s.id FROM account_auth_session s
JOIN account_refresh_token r ON r.session_id = s.id
WHERE r.token_hash = #{refreshHash}

SELECT id AS session_id, absolute_expires_at
FROM account_auth_session
WHERE account_id = #{accountId} AND access_token_hash = #{accessHash}
  AND status = 'ACTIVE' AND access_expires_at > #{now} AND absolute_expires_at > #{now}
FOR UPDATE

mapper.update:
UPDATE account_auth_session
SET status = 'REVOKED', revoked_at = #{revokedAt}, updated_at = #{revokedAt}
WHERE account_id = #{accountId} AND id != #{currentSessionId} AND status = 'ACTIVE'
